#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Define a stack size slightly larger than the minimum requirement
// PTHREAD_STACK_MIN is usually 16384 bytes (16 KB)
#define CUSTOM_STACK_SIZE (PTHREAD_STACK_MIN + 32768) 

void* thread_function(void* arg) {
    printf("\tThread created with custom stack attributes.\n");
    return NULL;
}

int main() {
    pthread_attr_t attr;
    pthread_t thread_id;
    size_t initial_size, retrieved_size;
    int s;

    // 1. Initialize attributes object
    s = pthread_attr_init(&attr);
    if (s != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", s);
        return 1;
    }

    // 2. Get the default stack size for verification
    pthread_attr_getstacksize(&attr, &initial_size);
    printf("Default stack size: %zu bytes\n", initial_size);

    // 3. Set the custom stack size attribute
    printf("Setting custom stack size to: %zu bytes\n", CUSTOM_STACK_SIZE);
    s = pthread_attr_setstacksize(&attr, CUSTOM_STACK_SIZE);
    if (s != 0) {
        fprintf(stderr, "Error setting stack size (EINVAL likely): %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 4. Verify the change by retrieving the set value
    pthread_attr_getstacksize(&attr, &retrieved_size);
    printf("Retrieved custom stack size: %zu bytes\n", retrieved_size);

    // 5. Create the thread using the customized attributes
    s = pthread_create(&thread_id, &attr, thread_function, NULL);
    if (s != 0) {
        fprintf(stderr, "Error creating thread: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    // 6. Clean up attributes object
    pthread_attr_destroy(&attr);

    printf("Main thread exiting.\n");
    return 0;
}
